package com.example.lending.application.service;

import com.example.lending.application.port.in.ListActiveLoansUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadLoanPort.ActiveLoanSlice;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@Transactional(readOnly = true)
public class ListActiveLoansService implements ListActiveLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;

    public ListActiveLoansService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public ActiveLoanPage listActiveLoans(ListActiveLoansQuery query) {
        Member member = loadMemberPort.loadMember(query.memberId())
                .orElseThrow(() -> new MemberNotFoundException(query.memberId()));
        ActiveLoanSlice slice = loadLoanPort.loadActiveLoans(member.getId(), query.page(), query.size());

        Map<UUID, String> titles = loadTitles(slice.loans());
        List<ActiveLoanItem> items = slice.loans().stream()
                .map(loan -> toItem(loan, titles))
                .toList();
        return new ActiveLoanPage(items, query.page(), query.size(), slice.totalCount());
    }

    private Map<UUID, String> loadTitles(List<Loan> loans) {
        Set<UUID> bookIds = loans.stream().map(Loan::getBookId).collect(Collectors.toSet());
        return loadBookPort.loadBooks(bookIds).stream()
                .collect(Collectors.toMap(Book::getId, Book::getTitle));
    }

    private ActiveLoanItem toItem(Loan loan, Map<UUID, String> titles) {
        String title = titles.get(loan.getBookId());
        if (title == null) {
            throw new BookNotFoundException(loan.getBookId());
        }
        return new ActiveLoanItem(loan.getId(), loan.getBookId(), title, loan.getLoanedAt(), loan.getDueAt());
    }
}
